#!/usr/bin/env node
// Web test fixtures (design docs/design/web-test-fixtures.md, #564): writes one fixture file per
// generated file, `web/src/shared/testing/fixtures/<name>.ts`, with one `make<Type>` factory per
// generated object type, plus `index.ts`.
//
//   node scripts/gen-fixtures.mjs           write the fixtures
//   node scripts/gen-fixtures.mjs --check   write nothing; exit 1 and list every missing, stale or
//                                          orphaned fixture file (the guard test runs this)
//
// It reads the ts-rs output as text. Never edit the fixture files by hand; rerun this instead.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const WEB = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const GEN_DIR = path.join(WEB, 'src/shared/api/generated');
const FIX_DIR = path.join(WEB, 'src/shared/testing/fixtures');
const HEADER =
  '// GENERATED by web/scripts/gen-fixtures.mjs from src/shared/api/generated (docs/design/web-test-fixtures.md).\n' +
  '// Do not edit by hand: run `npm run gen:fixtures`. A guard test fails when this file is stale.\n';

/** The generic wrappers get hand-shaped factories that take the payload (design §2). */
const GENERICS = {
  ViewAnswer: { params: 'data: T', body: '{ version: 0, changed: true, data, ...o }' },
  OrgViewAnswer: { params: 'data: T', body: '{ changed: true, versions: {}, data, ...o }' },
  Part: { params: 'data: T | null', body: '{ available: data !== null, reason: null, data, ...o }' },
};

const MONEY_NAME = /(amount|price|rate|fee|total|balance|quantity|limit|thb|share)$/i;

// ---------- parsing ----------

function stripComments(s) {
  return s.replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/.*$/gm, '');
}

/** Splits `s` at top-level occurrences of `sep` (outside <>, {}, [], () and string literals). */
function splitTop(s, sep) {
  const out = [];
  let depth = 0;
  let quote = null;
  let cur = '';
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (quote) {
      cur += ch;
      if (ch === quote && s[i - 1] !== '\\') quote = null;
      continue;
    }
    if (ch === '"' || ch === "'") {
      quote = ch;
      cur += ch;
      continue;
    }
    if ('<{[('.includes(ch)) depth++;
    if ('>}])'.includes(ch)) depth--;
    if (ch === sep && depth === 0) {
      out.push(cur);
      cur = '';
    } else cur += ch;
  }
  if (cur.trim()) out.push(cur);
  return out.map((x) => x.trim()).filter((x) => x !== '');
}

/** `{ a: T, b?: U, }` body → [{ name, optional, type }]. */
function parseFields(body) {
  return splitTop(body, ',').map((part) => {
    const m = part.match(/^("[^"]+"|[\w$]+)(\??)\s*:\s*([\s\S]+)$/);
    if (!m) throw new Error(`cannot parse field: ${part}`);
    return { name: m[1], optional: m[2] === '?', type: m[3].replace(/\s+/g, ' ').trim() };
  });
}

/** Reads every generated file: its exported types and the types it imports from siblings. */
function readGenerated() {
  const files = fs
    .readdirSync(GEN_DIR)
    .filter((f) => f.endsWith('.ts'))
    .sort();
  const modules = [];
  for (const file of files) {
    const base = file.slice(0, -3);
    const src = stripComments(fs.readFileSync(path.join(GEN_DIR, file), 'utf8'));
    const imports = {};
    for (const m of src.matchAll(/^import type \{([^}]*)\} from "\.\/([\w-]+)";/gm)) {
      for (const n of m[1].split(',').map((x) => x.trim()).filter(Boolean)) imports[n] = m[2];
    }
    const types = [];
    const re = /^export type (\w+)(<[^=]*>)? = ([\s\S]*?);\s*$/gm;
    for (const m of src.matchAll(re)) {
      const rhs = m[3].trim();
      const generic = Boolean(m[2]);
      if (rhs.startsWith('{') && rhs.endsWith('}')) {
        types.push({ name: m[1], kind: 'object', generic, fields: parseFields(rhs.slice(1, -1)) });
      } else {
        types.push({ name: m[1], kind: 'alias', generic, rhs });
      }
    }
    modules.push({ base, imports, types });
  }
  return modules;
}

// ---------- defaults ----------

function snake(name) {
  return name.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase();
}

function stringDefault(field, owner) {
  const n = field.replace(/"/g, '');
  if (/(^id$|Id$|_id$)/.test(n)) return `'${snake(owner)}-1'`;
  if (MONEY_NAME.test(n)) return "'0.00'";
  if (/Date$/.test(n) || /^date$/i.test(n)) return "'2026-01-01'";
  if (/(At$|_at$|Time$|^at$)/.test(n)) return "'2026-01-01T00:00:00Z'";
  if (/^(currency|code)$/i.test(n)) return "'USD'";
  return `'${n}'`;
}

class Gen {
  constructor(modules) {
    this.byName = new Map();
    for (const mod of modules) for (const t of mod.types) if (!this.byName.has(t.name)) this.byName.set(t.name, { mod, t });
  }

  /** The default expression for a field of TS type `type` named `field` in object type `owner`. */
  value(type, field, owner, ctx, seen) {
    const t = type.trim();
    const alts = splitTop(t, '|');
    if (alts.length > 1) {
      if (alts.includes('null')) return 'null';
      return this.value(alts[0], field, owner, ctx, seen);
    }
    if (t === 'string') return stringDefault(field, owner);
    if (t === 'number') return '0';
    if (t === 'boolean') return 'false';
    if (t === 'null') return 'null';
    if (t === 'unknown' || t === 'any') return 'null';
    if (/^(["']).*\1$/.test(t)) return `'${t.slice(1, -1).replace(/'/g, "\\'")}'`;
    if (/^\{ *\[key in /.test(t)) return '{}';
    if (t.startsWith('{')) {
      const fields = parseFields(t.slice(1, -1));
      return `{ ${fields
        .filter((f) => !f.optional)
        .map((f) => `${f.name}: ${this.value(f.type, f.name, owner, ctx, seen)}`)
        .join(', ')} }`;
    }
    if (t.endsWith('[]') || t.startsWith('Array<')) return '[]';
    if (t.startsWith('Record<')) return '{}';
    const g = t.match(/^(\w+)<([\s\S]*)>$/);
    if (g && GENERICS[g[1]]) {
      ctx.use(g[1]);
      // The payload's type is passed explicitly: from `null` alone, T would not be the field's type.
      for (const id of g[2].match(/\b[A-Z]\w*\b/g) ?? []) if (this.byName.has(id)) ctx.useType(id);
      return g[1] === 'Part' ? `makePart<${g[2]}>(null)` : `make${g[1]}<${g[2]}>(null as never)`;
    }
    if (/^\w+$/.test(t)) return this.named(t, field, owner, ctx, seen);
    throw new Error(`no default for type \`${t}\` (field ${owner}.${field})`);
  }

  named(name, field, owner, ctx, seen) {
    const hit = this.byName.get(name);
    if (!hit) throw new Error(`unknown type ${name} (field ${owner}.${field})`);
    if (hit.t.kind === 'alias') return this.value(hit.t.rhs, field, owner, ctx, seen);
    if (seen.includes(name)) throw new Error(`required-field cycle: ${[...seen, name].join(' → ')}`);
    ctx.use(name);
    // Visit it once to detect a cycle through required fields.
    this.objectBody(hit.t, ctx.child(), [...seen, name]);
    return `make${name}()`;
  }

  objectBody(t, ctx, seen) {
    return t.fields
      .filter((f) => !f.optional)
      .map((f) => `    ${f.name}: ${this.value(f.type, f.name, t.name, ctx, seen)},`)
      .join('\n');
  }
}

// ---------- emitting ----------

function render(modules) {
  const gen = new Gen(modules);
  const out = new Map();
  const exportsByFile = new Map();
  for (const mod of modules) {
    const local = new Set(mod.types.map((t) => t.name));
    const factoryUses = new Set();
    const typeUses = new Set();
    const ctx = {
      use: (n) => factoryUses.add(n),
      useType: (n) => typeUses.add(n),
      child: () => ({ use: () => {}, useType: () => {}, child: () => ctx.child() }),
    };
    const blocks = [];
    const makers = [];
    for (const t of mod.types) {
      if (t.kind !== 'object') continue;
      if (t.generic) {
        const spec = GENERICS[t.name];
        if (!spec) throw new Error(`generic object type ${t.name} has no hand-shaped factory in GENERICS`);
        blocks.push(
          `export function make${t.name}<T>(${spec.params}, o: Partial<${t.name}<T>> = {}): ${t.name}<T> {\n` +
            `  return ${spec.body};\n}`,
        );
      } else {
        const body = gen.objectBody(t, ctx, [t.name]);
        blocks.push(
          `export function make${t.name}(o: Partial<${t.name}> = {}): ${t.name} {\n` +
            `  return {\n${body}${body ? '\n' : ''}    ...o,\n  };\n}`,
        );
      }
      makers.push(`make${t.name}`);
    }
    // Imports: this file's types (all of them, re-exported for tests) and sibling factories.
    const typeNames = mod.types.map((t) => t.name);
    const lines = [HEADER];
    // Type imports: this file's object types, plus any generated type a generic payload names.
    const typeFrom = new Map();
    const addType = (n, from) => {
      if (!typeFrom.has(from)) typeFrom.set(from, new Set());
      typeFrom.get(from).add(n);
    };
    for (const t of mod.types) if (t.kind === 'object') addType(t.name, mod.base);
    for (const n of typeUses) addType(n, local.has(n) ? mod.base : (mod.imports[n] ?? gen.byName.get(n).mod.base));
    for (const [from, names] of [...typeFrom].sort((a, b) => (a[0] === mod.base ? -1 : b[0] === mod.base ? 1 : a[0].localeCompare(b[0])))) {
      lines.push(`import type { ${[...names].sort().join(', ')} } from '../../api/generated/${from}';`);
    }
    const bySibling = new Map();
    for (const n of [...factoryUses].sort()) {
      if (local.has(n)) continue;
      const hit = gen.byName.get(n);
      const from = mod.imports[n] ?? hit.mod.base;
      if (!bySibling.has(from)) bySibling.set(from, []);
      bySibling.get(from).push(`make${n}`);
    }
    for (const [from, names] of [...bySibling].sort()) lines.push(`import { ${names.join(', ')} } from './${from}';`);
    lines.push('');
    lines.push(`export type { ${typeNames.join(', ')} } from '../../api/generated/${mod.base}';`);
    if (blocks.length) lines.push('', blocks.join('\n\n'));
    out.set(`${mod.base}.ts`, lines.join('\n') + '\n');
    exportsByFile.set(mod.base, { types: typeNames, makers });
  }
  // index.ts: re-export everything; a name exported by several files is re-exported explicitly
  // from the first, which resolves the `export *` ambiguity.
  const owners = new Map();
  for (const [base, ex] of exportsByFile) for (const n of [...ex.types, ...ex.makers]) {
    if (!owners.has(n)) owners.set(n, []);
    owners.get(n).push(base);
  }
  const idx = [HEADER];
  for (const base of exportsByFile.keys()) idx.push(`export * from './${base}';`);
  const dups = [...owners].filter(([, b]) => b.length > 1).sort();
  for (const [n, bases] of dups) {
    const isType = !n.startsWith('make');
    idx.push(`export { ${isType ? 'type ' : ''}${n} } from './${bases[0]}';`);
  }
  out.set('index.ts', idx.join('\n') + '\n');
  return out;
}

// ---------- main ----------

const check = process.argv.includes('--check');
const files = render(readGenerated());
const problems = [];
const existing = fs.existsSync(FIX_DIR)
  ? fs.readdirSync(FIX_DIR).filter((f) => f.endsWith('.ts') && !f.endsWith('.test.ts'))
  : [];
for (const [name, text] of files) {
  const p = path.join(FIX_DIR, name);
  const cur = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null;
  if (cur === text) continue;
  if (check) problems.push(cur === null ? `missing: ${name}` : `stale: ${name}`);
  else {
    fs.mkdirSync(FIX_DIR, { recursive: true });
    fs.writeFileSync(p, text);
  }
}
for (const f of existing) {
  if (files.has(f)) continue;
  if (check) problems.push(`orphaned (no generated file): ${f}`);
  else fs.rmSync(path.join(FIX_DIR, f));
}
if (check && problems.length) {
  console.error('fixtures are out of date — run `npm run gen:fixtures`:\n  ' + problems.join('\n  '));
  process.exit(1);
}
console.log(check ? `fixtures up to date (${files.size} files)` : `wrote ${files.size} fixture files`);
